// ——— Health Check 결과 집계 + Supabase INSERT 준비 ———

const getResult = (nodeName) => {
  try { return $(nodeName).first()?.json ?? null; }
  catch { return null; }
};

const health = getResult('Check 1: Health');
const callback = getResult('Check 2: Callback');
const firecrawl = getResult('Check 3: Firecrawl');
const observatory = getResult('Check 4: Observatory');

// ——— 판정 로직 ———
const checks = [];

// Health
const hs = health?.statusCode;
if (hs === 308 || hs === 301) {
  checks.push({ name: 'Vercel Health', status: 'critical', code: hs, detail: '도메인 redirect 감지 — 콜백 URL stale 가능성' });
} else if (hs >= 200 && hs < 400) {
  checks.push({ name: 'Vercel Health', status: 'healthy', code: hs, detail: '' });
} else {
  checks.push({ name: 'Vercel Health', status: 'critical', code: hs || 0, detail: '서비스 다운 또는 타임아웃' });
}

// Callback
const cs = callback?.statusCode;
if (cs === 308 || cs === 301) {
  checks.push({ name: 'Callback URL', status: 'critical', code: cs, detail: 'POST→GET 변환 위험! URL 확인 필요' });
} else if (cs === 401) {
  checks.push({ name: 'Callback URL', status: 'warning', code: cs, detail: 'Bearer 토큰 만료 의심' });
} else if (cs === 400 || cs === 422) {
  checks.push({ name: 'Callback URL', status: 'healthy', code: cs, detail: 'Probe 거부 = 정상' });
} else if (cs >= 500) {
  checks.push({ name: 'Callback URL', status: 'critical', code: cs, detail: '서버 에러' });
} else {
  checks.push({ name: 'Callback URL', status: 'critical', code: cs || 0, detail: '응답 없음' });
}

// Firecrawl
const fs = firecrawl?.statusCode;
if (fs && fs < 500) {
  checks.push({ name: 'Firecrawl API', status: 'healthy', code: fs, detail: '' });
} else {
  checks.push({ name: 'Firecrawl API', status: 'critical', code: fs || 0, detail: '서비스 장애' });
}

// Observatory
const os = observatory?.statusCode;
if (os && os < 500) {
  checks.push({ name: 'Observatory v2', status: 'healthy', code: os, detail: '' });
} else {
  checks.push({ name: 'Observatory v2', status: 'critical', code: os || 0, detail: '서비스 장애 — v1 종료 패턴 의심' });
}

const criticalCount = checks.filter(c => c.status === 'critical').length;
const warningCount = checks.filter(c => c.status === 'warning').length;
let overallStatus = 'healthy';
if (criticalCount > 0) overallStatus = 'critical';
else if (warningCount > 0) overallStatus = 'warning';

return [{
  json: {
    overall_status: overallStatus,
    critical_count: criticalCount,
    warning_count: warningCount,
    checks,
    execution_id: $execution.id,
    shouldAlert: criticalCount > 0 || warningCount > 0,
  }
}];

// ——— 알림 생성 + Supabase alerts 테이블 INSERT 준비 ———
const data = $('Aggregate Results').first().json;

const failedChecks = data.checks.filter(c => c.status !== 'healthy');
const message = [
  `🚨 Pipeline ${data.overall_status.toUpperCase()}`,
  `Time: ${new Date().toISOString()}`,
  '',
  ...failedChecks.map(c => `• ${c.name}: ${c.status} [${c.code}] — ${c.detail}`),
].join('\n');

const severity = data.critical_count > 0 ? 'critical' : 'warning';

return [{
  json: {
    // Supabase alerts INSERT용
    alert_type: `health_${severity}`,
    severity,
    message,
    // Slack/Email용
    slackMessage: message,
  }
}];
